package gg.pixelkingdomwars.nativeclient.audio

import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test

class BattleAudioPlanTest {
    private val bounds = BattleAudioBounds.from(audioReference.getValue("catalogue").jsonObject)
    @Test fun `all canonical event cases match exact source timing keys families and dispatch`() {
        // Generated by executing clean source6d69 battleAudio.ts, not by this Kotlin implementation.
        val cases = audioReference.getValue("cases").jsonArray
        assertEquals(21, cases.size)
        cases.forEach { value ->
            val case = value.jsonObject
            val name = case.getValue("name").jsonPrimitive.content
            val buildings = case.getValue("buildings").jsonArray.associate {
                it.jsonObject.getValue("id").jsonPrimitive.content to it.jsonObject.getValue("type").jsonPrimitive.content
            }
            val actual = BattleAudioPlan(bounds).plan(case.getValue("events").jsonArray.map { it.jsonObject }, buildings)
            val expected = case.getValue("expected").jsonArray.map { raw ->
                val cue = raw.jsonObject; val opts = cue["opts"] as? JsonObject
                BattleAudioCue(cue.getValue("atMs").jsonPrimitive.double, cue.getValue("family").jsonPrimitive.content,
                    cue.getValue("variantKey").jsonPrimitive.content, cue["fallback"]?.jsonPrimitive?.content,
                    opts?.get("loop")?.jsonPrimitive?.booleanOrNull ?: false, opts?.get("volume")?.jsonPrimitive?.floatOrNull ?: 1f,
                    when (opts?.get("priority")?.jsonPrimitive?.content) { "critical" -> AudioPriority.CRITICAL; "ambient" -> AudioPriority.AMBIENT; else -> AudioPriority.NORMAL },
                    when (cue["dispatch"]?.jsonPrimitive?.content) { "actorLoop" -> AudioDispatch.ACTOR_LOOP; "kegPrime" -> AudioDispatch.KEG_PRIME; else -> null })
            }
            assertEquals(name, expected, actual)
        }
    }
    @Test fun `cold prefix background silence and jump cannot catch up old cues`() {
        val cursor = BattleAudioCursor()
        val cues = listOf(10.0, 20.0, 30.0, 40.0).map { BattleAudioCue(it, "family", "$it") }
        cursor.replace(cues, 15.5)
        assertEquals(listOf(cues[1]), cursor.advance(20.0, true))
        assertEquals(emptyList<BattleAudioCue>(), cursor.advance(30.0, false))
        assertEquals(emptyList<BattleAudioCue>(), cursor.advance(35.0, true))
        assertEquals(emptyList<BattleAudioCue>(), cursor.advance(40.0, true, jumped = true))
        assertEquals(emptyList<BattleAudioCue>(), cursor.advance(41.0, true))
    }
    @Test fun `actor loops and keg prime stay owned by actor lifecycle instead of duplicate one shots`() {
        val cursor = BattleAudioCursor()
        val one = BattleAudioCue(1.0, "blast", "1")
        cursor.replace(listOf(one.copy(dispatch = AudioDispatch.ACTOR_LOOP), one.copy(dispatch = AudioDispatch.KEG_PRIME), one), 0.0)
        assertEquals(listOf(one), cursor.advance(1.0, true))
    }
    @Test fun `replacement drops old revision schedule and only admits current future events`() {
        val cursor = BattleAudioCursor(); val old = BattleAudioCue(20.0, "old", "old")
        cursor.replace(listOf(old), 0.0); cursor.advance(10.0, true)
        val corrected = old.copy(atMs = 21.0, family = "corrected")
        cursor.replace(listOf(corrected), 10.5)
        assertTrue(cursor.advance(20.0, true).isEmpty())
        assertEquals(listOf(corrected), cursor.advance(21.0, true))
        assertThrows(IllegalArgumentException::class.java) { cursor.advance(20.0, true) }
    }
    @Test fun `replay event bound is enforced before expansion`() {
        assertThrows(IllegalArgumentException::class.java) {
            BattleAudioPlan(bounds.copy(maxEvents = 1)).plan(listOf(buildJsonObject {}, buildJsonObject {}), emptyMap())
        }
    }
    @Test fun `rolling bank prioritizes sounds without fallbacks and selects only requested windows`() {
        val manifest = Json.parseToJsonElement("""{"schemaVersion":1,"entries":[
          {"id":"sfx_battle_rally_v1","file":"rally.wav"},{"id":"sfx_battle_star_1_v1","file":"star.wav"}
        ]}""").jsonObject
        val definitions = AudioDefinitions.from(audioPack(paths = listOf("audio/sfx-ai/rally.wav", "audio/sfx-ai/star.wav")), manifest)
        val window = audioRuntime().battleBankWindowMs.toDouble()
        val cues = listOf(BattleAudioCue(1.0, "sfx_battle_rally", "a", "sfx_rally_horn"),
            BattleAudioCue(2.0, "sfx_battle_star_1", "b"), BattleAudioCue(window, "sfx_battle_rally", "c"))
        val result = battleAudioWindows(cues, definitions, audioRuntime())
        assertEquals(listOf(0L, window.toLong()), result.map { it.startMs })
        assertEquals(listOf("sfx_battle_star_1_v1", "sfx_battle_rally_v1"), result[0].definitions.map { it.id })
        assertEquals(listOf("sfx_battle_rally_v1"), result[1].definitions.map { it.id })
    }
    @Test fun `late frame resets locate the next cue without rescanning a dense journal`() {
        var reads = 0
        val cues = object : AbstractList<BattleAudioCue>() {
            override val size = 100_000
            override fun get(index: Int): BattleAudioCue { reads++; return BattleAudioCue(index.toDouble(), "family", "$index") }
        }
        val cursor = BattleAudioCursor(); cursor.replace(cues, 99_999.0)
        assertTrue("A reset should search the sorted index", reads <= 18)
        assertEquals(listOf(BattleAudioCue(99_999.0, "family", "99999")), cursor.advance(99_999.0, true))
    }

    @Test fun `obsolete audio planning cancels before traversing the remaining accepted journal`() {
        val event = buildJsonObject { put("t", 0); put("e", "star"); put("n", 1) }
        var checks = 0
        assertThrows(java.util.concurrent.CancellationException::class.java) {
            BattleAudioPlan(bounds).plan(List(1_000) { event }, emptyMap()) {
                if (++checks == 20) throw java.util.concurrent.CancellationException()
            }
        }
        assertEquals(20, checks)
    }

}
